function refreshKidsReading(products){const previous={"kids-color-story": "ต้นแบบ PDF ไทย-อังกฤษ 20 หน้า: 8 ภาพสัตว์ระบายสี + 8 หน้าวาดต่อ + ส่วนประกอบ 4 หน้า มี A4 และ US Letter เนื้อหาเดียวกัน แนวเริ่มต้นประมาณ 4-7 ปี เลือกตามความพร้อมเด็ก", "kids-add-subtract": "ต้นแบบ PDF ไทย-อังกฤษ 48 หน้า: แบบฝึก 40 หน้า รวม 400 ข้อ พร้อมเฉลย 8 หน้า บวกและลบช่วง 0-10 และ 0-20 มี A4/US Letter เนื้อหาเดียวกัน โจทย์มีซ้ำข้ามหน้าเพื่อทบทวน", "kids-color-numbers": "ต้นแบบชุดรวม 68 หน้า: ระบายสีและวาดต่อ 20 หน้า + แบบฝึกเลข 40 หน้า + เฉลย 8 หน้า เป็นการรวมสองชุดเดิม มี A4 และ US Letter เนื้อหาเดียวกัน"};for(const product of products){if(product.description===previous[product.id]){const next=LAUNCH_PRODUCTS.find(x=>x.id===product.id);product.description=next.description;if(product.id==='kids-color-story'&&product.name==='ระบายสี แล้วเล่าเรื่องของหนู')product.name=next.name;}}}
